export default function AdminDashboard() {
  const [active, setActive] = useState("overview");
  const [reservations, setReservations] = useState([]);
  const [reservationError, setReservationError] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    let isCurrent = true;
    apiRequest("/reservations")
      .then(({ reservations: records }) => {
        if (isCurrent) setReservations(records.map(toDashboardReservation));
      })
      .catch((error) => {
        if (isCurrent) setReservationError(error.message);
      });
    return () => { isCurrent = false; };
  }, []);

  async function updateReservationStatus(reservation, status) {
    try {
      await apiRequest(`/reservations/${reservation.reservationId}/status`, {
        method: "PATCH",
        body: JSON.stringify({ status }),
      });
      setReservations((current) => current.map((item) => item.reservationId === reservation.reservationId ? { ...item, status } : item));
      setReservationError("");
    } catch (error) {
      setReservationError(error.message);
    }
  }

  const handleLogout = () => {
    clearSession();
    navigate("/login");
  };

  const panels = { overview: <Overview reservations={reservations} />, reservations: <Reservations reservations={reservations} onStatusChange={updateReservationStatus} />, transactions: <Transactions />, customers: <Customers />, services: <Services />, reports: <Reports />, settings: <Settings /> };
  const sections = ["Main", "Management", "Analytics"];

  return (
    <div style={S.shell}>
      <aside style={S.sidebar}>
        <div style={S.logoBox}>
          <div style={S.logoDot} />
          <div>
            <p style={S.logoTitle}>Villa Tjeozabel</p>
            <p style={S.logoSub}>Admin Dashboard</p>
          </div>
        </div>

        <nav style={{ flex: 1 }}>
          {sections.map(section => (
            <div key={section}>
              <div style={S.navSection}>{section}</div>
              {NAV.filter(n => n.section === section).map(n => (
                <button key={n.id} style={S.navItem(active === n.id)} onClick={() => setActive(n.id)}>
                  <i className={`bi ${n.icon}`} style={{ fontSize: 17 }} />
                  {n.label}
                </button>
              ))}
            </div>
          ))}
        </nav>

        <button style={S.logoutBtn} onClick={handleLogout}>
          <i className="bi bi-box-arrow-left" style={{ fontSize: 17 }} />
          Logout
        </button>
      </aside>

      <div style={S.main}>
        <div style={S.topbar}>
          <span style={S.topbarTitle}>{NAV.find(n => n.id === active)?.label}</span>
          <div style={S.topbarRight}>
            <div style={S.notifBtn}>
              <i className="bi bi-bell" style={{ fontSize: 18, color: "#374151" }} />
              <span style={S.notifBadge}>3</span>
            </div>
            <div style={S.profileBox}>
              <div style={S.profileAvatar}>AD</div>
              <div>
                <p style={S.profileName}>Geeyan Sanico</p>
                <p style={S.profileRole}>Admin</p>
              </div>
            </div>
          </div>
        </div>

        <div style={S.content}>
          {reservationError && <p role="alert" style={{ color: "#b42318" }}>{reservationError}</p>}
          {panels[active]}
        </div>
      </div>
    </div>
  );
}
